        headers: { Authorization: `Bearer ${authToken}` },
        body: formData,
      });
      const data = await response.json();
      if (!response.ok) {
        setError(data.error || 'Unable to create participant');
        return;
      }
      setStatus('Participant created successfully');
      setForm(emptyForm);
      fetchUsers();
    } catch (err) {
      setError('Create participant failed');
    }
  };

  const handleSelect = (user) => {
    setSelected(user);
    setForm({
      name: user.name || '',
      email: user.email || '',
      password: '',
      role: user.role || 'participant',
      birthDate: user.birthDate || '',
      profileImage: null,
      imagePreview: user.imageUrl || '',
    });
    setStatus('Editing ' + user.name);
    setError('');
  };

  const handleUpdate = async (event) => {
    event.preventDefault();
    if (!selected) return;
    setError('');
    setStatus('');

    try {
      const formData = new FormData();
      formData.append('targetId', selected.id);
      formData.append('name', form.name);
      formData.append('email', form.email);
      formData.append('birthDate', form.birthDate);
      formData.append('role', form.role);
